mapper.insert:
INSERT /* SQL_ID: NotifcMapper.insertNotifc */
       INTO dtmeta.tb_portal_notifc
     ( notifc_id
     , user_id
     , notifc_msg
     , notifc_link_url
     , notifc_type_id
     , notifc_rqtr_div_mtcd
     , notifc_rqtr_id
     , notifc_rqtr_nm
     , notifc_reg_dt
     ) VALUES 
     ( 
       #{notifcId}                        
     , #{userId}
     , #{notifcMsg}
     , #{notifcLinkUrl}
     , #{notifcTypeId}
     , #{notifcRqtrDivMtcd}
     , #{notifcRqtrId}
     , #{notifcRqtrNm}
     , current_timestamp
     )

mapper.delete:
DELETE /* SQL_ID: NotifcMapper.deleteNotifc */
  FROM dtmeta.tb_portal_notifc
 WHERE notifc_id          = #{notifcId}

mapper.select:
SELECT /* SQL_ID: NotifcMapper.selectMyNotifcSettingCount */ COUNT(*) FROM dtmeta.tb_portal_notifctype t1 INNER JOIN ( SELECT DISTINCT notifc_type_id FROM dtmeta.tb_portal_notifctarget t2 WHERE ( POSITION (CONCAT(',', #{loginUserId}, ',') IN CONCAT(',', t2.notifc_tgtr_ids, ',')) != 0
OR POSITION (CONCAT(',', #{item}, ',') IN CONCAT(',', t2.notifc_tgtr_ids, ',')) != 0
) ) t2 ON t1.notifc_type_id = t2.notifc_type_id LEFT OUTER JOIN dtmeta.tb_portal_notifcsettings t3 ON t1.notifc_type_id = t3.notifc_type_id AND t3.user_id = #{loginUserId} WHERE t1.notifc_use_yn = 'Y'

SELECT /* SQL_ID: NotifcMapper.selectMyNotifcSettingList */ t1.notifc_type_id , t1.notifc_type_nm , t1.notifc_msg_rstrtn_len , t1.notifc_msg_tmplt , t1.notifc_link_tmplt_url , string_agg(t2.mtcd_nm, ',' ORDER BY t2.mtcd_sort_odrg) AS notifc_tgt_type_mtcd_nm_str , t3.notifc_setup_id , #{loginUserId} AS user_id , COALESCE(t3.notifc_rcv_yn, 'Y') AS notifc_rcv_yn , COALESCE(t3.notifc_popup_yn, 'Y') AS notifc_popup_yn FROM dtmeta.tb_portal_notifctype t1 INNER JOIN ( SELECT DISTINCT notifc_type_id, c1.mtcd_nm, c1.mtcd_sort_odrg FROM dtmeta.tb_portal_notifctarget t2 LEFT OUTER JOIN dtmeta.tb_portal_code c1 ON t2.notifc_tgt_type_mtcd = c1.mtcd AND c1.mtcd_grp_id = 'MCG00019' WHERE ( POSITION (CONCAT(',', #{loginUserId}, ',') IN CONCAT(',', t2.notifc_tgtr_ids, ',')) != 0
OR POSITION (CONCAT(',', #{item}, ',') IN CONCAT(',', t2.notifc_tgtr_ids, ',')) != 0
) ) t2 ON t1.notifc_type_id = t2.notifc_type_id LEFT OUTER JOIN dtmeta.tb_portal_notifcsettings t3 ON t1.notifc_type_id = t3.notifc_type_id AND t3.user_id = #{loginUserId} WHERE t1.notifc_use_yn = 'Y' GROUP BY ( t1.notifc_type_id , t1.notifc_type_nm , t1.notifc_msg_rstrtn_len , t1.notifc_msg_tmplt , t1.notifc_link_tmplt_url , t3.notifc_setup_id , t3.notifc_rcv_yn , t3.notifc_popup_yn ) ORDER BY t1.notifc_type_sort_odrg

mapper.insert:

    SELECT CONCAT('NTS', EXTRACT(EPOCH FROM now())::int, LPAD(CAST(NEXTVAL('dtmeta.seq_tb_portal_common') AS varchar), 4, '0'))

INSERT /* SQL_ID: NotifcMapper.insertNotifcSettingAutoKey */
       INTO dtmeta.tb_portal_notifcsettings
     ( notifc_setup_id
     , user_id
     , notifc_type_id
     , notifc_rcv_yn
     , notifc_popup_yn
     , notifc_setup_reg_dt
     , notifc_setup_amd_dt
     ) VALUES 
     ( 
       #{notifcSetupId}                        
     , #{userId}
     , #{notifcTypeId}
     , #{notifcRcvYn}
     , #{notifcPopupYn}
     , current_timestamp
     , current_timestamp
     )

mapper.update:
UPDATE /* SQL_ID: NotifcMapper.updateNotifcSetting */
       dtmeta.tb_portal_notifcsettings
   SET notifc_rcv_yn        = #{notifcRcvYn}
     , notifc_popup_yn      = #{notifcPopupYn}
     , notifc_setup_amd_dt  = current_timestamp            
 WHERE notifc_setup_id      = #{notifcSetupId}
